<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>VendorSync Dashboard</title>
  <style>
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body { font-family: system-ui, -apple-system, sans-serif; background: #f5f7fa; color: #222; padding: 24px; }
    .container { max-width: 900px; margin: 0 auto; }
    h1 { margin-bottom: 16px; font-size: 1.6rem; }

    /* States */
    .loading { color: #555; font-size: 1.1rem; margin-top: 32px; }
    .empty { color: #555; font-size: 1.1rem; margin-top: 32px; }
    .error-banner {
      background: #fee; border: 1px solid #c00; color: #c00;
      padding: 14px 18px; border-radius: 6px; margin-bottom: 16px; font-weight: 500;
    }

    /* Header bar */
    .header-bar {
      display: flex; align-items: center; justify-content: space-between;
      margin-bottom: 16px; flex-wrap: wrap; gap: 12px;
    }
    .summary-line { font-size: 1.05rem; color: #333; }
    .sync-btn {
      padding: 9px 18px; border: none; border-radius: 6px;
      background: #1a73e8; color: #fff; font-size: 0.95rem; cursor: pointer;
    }
    .sync-btn:hover { background: #1557b0; }
    .sync-btn:disabled { background: #a0c4ff; cursor: wait; }

    /* Last-sync badge */
    .last-sync { font-size: 0.85rem; color: #666; margin-bottom: 12px; }

    /* Table */
    table { width: 100%; border-collapse: collapse; background: #fff; border-radius: 8px; overflow: hidden; box-shadow: 0 1px 4px rgba(0,0,0,0.06); }
    th { background: #eef2f7; text-align: left; padding: 11px 14px; font-weight: 600; color: #333; border-bottom: 1px solid #ddd; }
    td { padding: 10px 14px; border-top: 1px solid #eee; }
    tr:hover td { background: #fafcff; }
    .status-paid { color: #1e8e3e; font-weight: 500; }
    .status-pending { color: #b07500; font-weight: 500; }
    .status-failed { color: #c00; font-weight: 500; }
    .status-default { color: #333; }
  </style>
</head>
<body>
  <div class="container">
    <h1>VendorSync Payments</h1>
    <div id="app"></div>
  </div>

  <script>
    (function () {
      const app = document.getElementById('app');

      // --- helpers ---

      function showLoading() {
        app.innerHTML = '<p class="loading">Loading payments&hellip;</p>';
      }

      function showError(msg) {
        app.innerHTML = '<div class="error-banner">' + escapeHtml(msg || 'Failed to load data. Check if the server is running.') + '</div>';
      }

      function escapeHtml(str) {
        return String(str)
          .replace(/&/g, '&amp;')
          .replace(/</g, '&lt;')
          .replace(/>/g, '&gt;');
      }

      async function fetchJson(url, options) {
        const res = await fetch(url, options);
        if (!res.ok) throw new Error('HTTP ' + res.status);
        return await res.json();
      }

      function statusClass(s) {
        if (s === 'paid') return 'status-paid';
        if (s === 'pending') return 'status-pending';
        if (s === 'failed') return 'status-failed';
        return 'status-default';
      }

      function formatCurrencyEur(minorUnits) {
        const value = Number(minorUnits) / 100;
        return value.toLocaleString('en-IE', { style: 'currency', currency: 'EUR' });
      }

      function formatDate(isoStr) {
        try {
          const d = new Date(isoStr);
          if (Number.isNaN(d.getTime())) return isoStr;
          return d.toLocaleString('en-IE');
        } catch {
          return isoStr;
        }
      }

      // --- main ---

      async function loadAll() {
        showLoading();
        try {
          const [health, summary, payments] = await Promise.all([
            fetchJson('/api/health'),
            fetchJson('/api/summary'),
            fetchJson('/api/payments?limit=100&offset=0')
          ]);

          const count = summary.count != null ? summary.count : (payments.total || 0);
          const items = Array.isArray(payments) ? payments : (payments.items || []);

          if (count === 0) {
            renderEmpty();
            return;
          }

          renderDashboard(health, summary, items);
        } catch (err) {
          console.error(err);
          showError('Failed to load data. Check if the server is running.');
        }
      }

      function renderEmpty() {
        app.innerHTML = '<p class="empty">No payments yet. Click Sync now.</p>';
      }

      function renderDashboard(health, summary, items) {
        const count = summary.count != null ? summary.count : items.length;
        const totalMinor = summary.total_minor || 0;
        const lastSync = health.last_sync || null;

        let html = '';

        // header bar
        html += '<div class="header-bar">';
        html += '<span class="summary-line">' + count + ' payment(s) &middot; Total: ' + formatCurrencyEur(totalMinor) + '</span>';
        html += '<button class="sync-btn" id="syncBtn">Sync now</button>';
        html += '</div>';

        // last sync line
        html += '<p class="last-sync">Last sync: ' + (lastSync ? formatDate(lastSync) : 'Never synced') + '</p>';

        // table
        html += '<table><thead><tr><th>Date</th><th>Amount</th><th>Status</th></tr></thead><tbody>';
        for (const p of items) {
          html += '<tr>';
          html += '<td>' + escapeHtml(formatDate(p.created_at)) + '</td>';
          html += '<td>' + formatCurrencyEur(p.amount_minor) + '</td>';
          html += '<td class="' + statusClass(p.status) + '">' + escapeHtml(String(p.status)) + '</td>';
          html += '</tr>';
        }
        html += '</tbody></table>';

        app.innerHTML = html;
      }

      // --- sync button ---

      document.addEventListener('DOMContentLoaded', () => {
        loadAll();

        app.addEventListener('click', async (e) => {
          if (e.target.id !== 'syncBtn') return;
          e.preventDefault();
          const btn = e.target;
          btn.disabled = true;
          try {
            const result = await fetchJson('/api/sync', { method: 'POST' });
            // result has {fetched, inserted, total}; just refresh.
            console.log('Sync done:', result);
          } catch (err) {
            console.error(err);
          } finally {
            btn.disabled = false;
          }
          await loadAll();
        });
      });
    })();
  </script>
</body>
</html>

```

